For the \ac{cl} tree estimated with $m$ vector samples $\hat{\mathcal{T}}_{\rm{SCL}}(m)$, the confident and unconfident edge sets are defined as
	\begin{align}
		\mathscr{C}_{\mathrm{E}}(m)&\triangleq \Big\{\{i,j\}\in\mathcal{E}\big(\hat{\mathcal{T}}_{\rm{SCL}}(m)\big) ~\Big|~\forall\, \{j,k\},\{l,i\}\in\mathcal{E}\big(\hat{\mathcal{T}}_{\rm{SCL}}(m)\big),~\mathcal{C}_{ijk}(m) \cap\mathcal{C}_{lij}(m) \text{ hold}\Big\}
		\end{align}
		and $\mathscr{C}_{\mathrm{E}}(m)^{\complement} \triangleq \mathcal{E}\big(\hat{\mathcal{T}}_{\rm{SCL}}(m)\big)\backslash \mathscr{C}_{\mathrm{E}}(m)$,



	respectively. The edges in $\mathscr{C}_{\mathrm{E}}(m)$ (resp.\ $\mathscr{C}_{\mathrm{E}}(m)^{\complement}$) are called confident (resp.\ unconfident) edges. The set of unconfident nodes  is defined as
	\begin{align}
		\mathscr{C}_{\mathrm{V}}(m)^{\complement}\triangleq \big\{i\in\mathcal{V} \ \big| \ \exists\,  j\in\mathcal{V} \text{ s.t. }\{i,j\}\in \mathscr{C}_{\mathrm{E}}(m)^{\complement} \big\}.
	\end{align}

For a homogeneous Ising tree with zero external field parameterized by $0<\rho<1$ that satisfies Assumption 1, $\hat{\mathcal{T}}_{\rm{SCL}}(\hat{\alpha} n)$ learned in  \ac{alathe} in Algorithm~algo:alathe satisfies
\begin{align} 
	\varliminf_{n\rightarrow\infty}-\frac{1}{n}\log\Pr\Big(\big(\mathcal{E}\big(\hat{\mathcal{T}}_{\rm{SCL}}(\hat{\alpha} n)\big)\backslash \mathcal{E}(\mathcal{T})\big)\cap \mathscr{C}_{\mathrm{E}}(\hat{\alpha} n)\neq \emptyset\Big)\geq c_{\rho}K _{{\rm passive}}(\rho),
\end{align}
where $\mathscr{C}_{\mathrm{E}}(\hat{\alpha} n)$ is the set of confident edges (see Definition 2).

For a homogeneous Ising tree with zero external field parameterized by $0<\rho<1$ that satisfies Assumption 1, the error exponent of the event that the subgraph of unconfident nodes in $\hat{\mathcal{T}}_{{\rm active}}(n)$ in Algorithm~algo:alathe is wrong is lower bounded as
\begin{align}
	K \Big(\big\{\hat{\mathcal{T}}_{{\rm active}}\big(\mathscr{C}_{\mathrm{V}}(\hat{\alpha} n)^{\complement}\big)\neq \mathcal{T}\big(\mathscr{C}_{\mathrm{V}}(\hat{\alpha} n)^{\complement}\big)\big\}_{n\in\mathbb{N}}\Big)\geq c_{\rho}K _{{\rm passive}}(\rho).
\end{align}

For the homogeneous Ising tree with zero external field $\mathcal{T}$ parameterized by $0<\rho<1$ that satisfies Assumption 1, the error exponent of the \ac{alathe} algorithm is at least $c_{\rho}$ times the 
	error exponent of the passive learning algorithm $K _{{\rm passive}}(\rho)$, i.e.,
	\begin{align}
		K _{{\rm active}}(\mathcal{T},\rho)\geq c_{\rho}K _{{\rm passive}}(\mathcal{T},\rho) \quad \forall\, \mathcal{T}\in\mathfrak{T}^{p},
	\end{align}
	where $c_{\rho}$ is the piecewise constant function   defined in Table~table:crho.

For a homogeneous Ising tree with zero external field parameterized by $0<\rho<1$ that satisfies Assumption 1, $\hat{\mathcal{T}}_{\rm{SCL}}(\hat{\alpha} n)$ learned in Algorithm~algo:alathe satisfies
\begin{align}
	K _{t}(\hat{\mathcal{T}}_{{\rm SCL}},\mathcal{T},\rho,P_{\hat{\alpha}})\geq c_{\rho}K _{{\rm passive}}(\rho) \text{ for all }t\geq 3,
\end{align}

For a homogeneous Ising tree with zero external field parameterized by $0<\rho<1$ that satisfies Assumption 1, the estimate $\hat{\rho}(\hat{\alpha} n)$ in Algorithm~algo:alathe satisfies 
\begin{align}
	\varliminf_{n\rightarrow\infty}-\frac{1}{n}\log\Pr\Big(\rho+\frac{2(1-\rho)}{9}<\hat{\rho}(\hat{\alpha} n)\Big)&\geq c_{\rho}K _{{\rm passive}}(\rho)\qquad\mbox{and}\\ \varliminf_{n\rightarrow\infty}-\frac{1}{n}\log\Pr\Big(\rho-\frac{1-\rho}{6}>\hat{\rho}(\hat{\alpha} n)\Big)&\geq c_{\rho}K _{{\rm passive}}(\rho).
\end{align}

For a homogeneous Ising tree with zero external field  parameterized by the correlation coefficient $0<\rho<1$ and satisfies Assumption 1, the packing number $N\big(\mathscr{C}_{\mathrm{E}}(\hat{\alpha} n)^{\complement},\mathcal{T}\big(\mathscr{C}_{\mathrm{V}}(\hat{\alpha} n)^{\complement}\big),2\big)$ of the unconfident edges set $\mathscr{C}_{\mathrm{E}}(\hat{\alpha} n)^{\complement}$ 
learned in Algorithm~algo:alathe satisfies
\begin{align}
	K\Big(\big\{N(\mathscr{C}_{\mathrm{E}}(\hat{\alpha} n)^{\complement},\mathcal{T}(\mathscr{C}_{\mathrm{V}}(\hat{\alpha} n)^{\complement}),2)\geq 13\big\}_{n\in\mathbb{N}}\Big)>c_{\rho}K _{{\rm passive}}(\rho).
\end{align}
